def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_c = sum(1 for a in opp if a == 'C')
    opp_d = n - opp_c
    my_c = sum(1 for a in me if a == 'C')
    my_d = n - my_c

    last_me = me[-1]
    last_opp = opp[-1]

    if opp_d == 0:
        if n < 4:
            return 'C'
        if n < 85:
            return 'C' if rng.random() < 0.97 else 'D'
        return 'D' if rng.random() < 0.6 else 'C'

    if opp_c == 0:
        if last_opp == 'D' and n > 6 and rng.random() < 0.05:
            return 'C'
        return 'D'

    recent_w = min(12, n)
    recent_opp = opp[-recent_w:]
    recent_me = me[-recent_w:]
    rec_opp_d = sum(1 for a in recent_opp if a == 'D')
    rec_opp_c = recent_w - rec_opp_d
    rec_me_d = sum(1 for a in recent_me if a == 'D')

    if rec_opp_d >= recent_w - 1:
        return 'D'

    if rec_opp_c >= recent_w - 1:
        if n >= 90:
            return 'D' if rng.random() < 0.35 else 'C'
        if last_opp == 'C' and last_me == 'D' and rng.random() < 0.85:
            return 'C'
        if rng.random() < 0.04:
            return 'D'
        return 'C'

    if last_opp == 'D' and last_me == 'C':
        if opp_d * 3 <= n and rng.random() < 0.25:
            return 'C'
        return 'D'

    if last_opp == 'D' and last_me == 'D':
        if rec_me_d >= recent_w - 1:
            return 'C'
        if rec_opp_d * 2 < recent_w:
            return 'C' if rng.random() < 0.65 else 'D'
        return 'D'

    if rec_opp_d * 3 >= recent_w:
        if last_opp == 'C' and rng.random() < 0.5:
            return 'C'
        return 'D'

    if rec_opp_d * 4 <= recent_w and rec_me_d * 3 >= recent_w:
        return 'C'

    if last_opp == 'C':
        if n >= 92:
            return 'D' if rng.random() < 0.25 else 'C'
        if rng.random() < 0.03:
            return 'D'
        return 'C'

    return 'C'
